+/**
+ * Sanitize an SVG DOM tree to remove XSS vectors.
+ * Removes script elements, javascript: URLs, and dangerous event handler attributes.
+ */
+
+/**
+ * List of element tag names that should be removed entirely (including children).
+ */
+const UNSAFE_ELEMENTS = [
+    'script',
+    'use' // can reference external content
+];
+
+/**
+ * Attribute names that are event handlers (start with 'on') or otherwise dangerous.
+ */
+const isUnsafeAttribute = function (attrName, attrValue) {
+    // Remove all event handler attributes (onclick, onload, onerror, etc.)
+    if (attrName.toLowerCase().startsWith('on')) {
+        return true;
+    }
+    // Remove javascript: URLs in href, xlink:href, src, action, etc.
+    if (['href', 'xlink:href', 'src', 'action', 'formaction', 'data'].includes(attrName.toLowerCase())) {
+        const trimmed = attrValue.replace(/\s/g, '').toLowerCase();
+        if (trimmed.startsWith('javascript:') || trimmed.startsWith('data:text/html')) {
+            return true;
+        }
+    }
+    return false;
+};
+
+/**
+ * Recursively sanitize an SVG element and its children.
+ * @param {Element} element - The DOM element to sanitize.
+ */
+const sanitizeElement = function (element) {
+    // Collect children to process (snapshot since we may remove nodes)
+    const children = Array.from(element.childNodes);
+
+    for (const child of children) {
+        if (child.nodeType === child.ELEMENT_NODE) {
+            const tagName = child.tagName ? child.tagName.toLowerCase() : '';
+
+            // Remove unsafe elements entirely
+            if (UNSAFE_ELEMENTS.includes(tagName)) {
+                element.removeChild(child);
+                continue;
+            }
+
+            // Remove unsafe attributes
+            if (child.attributes) {
+                const attrsToRemove = [];
+                for (const attr of Array.from(child.attributes)) {
+                    if (isUnsafeAttribute(attr.name, attr.value)) {
+                        attrsToRemove.push(attr.name);
+                    }
+                }
+                for (const attrName of attrsToRemove) {
+                    child.removeAttribute(attrName);
+                }
+            }
+
+            // Recurse into child elements
+            sanitizeElement(child);
+        }
+    }
+};
+
+/**
+ * Sanitize an SVG document/element to remove XSS vectors.
+ * @param {Document|Element} svgDocument - The SVG document or root element to sanitize.
+ * @returns {Document|Element} The sanitized document/element (mutated in place).
+ */
+const sanitizeSvg = function (svgDocument) {
+    const root = svgDocument.documentElement || svgDocument;
+
+    // Remove unsafe attributes from root element
+    if (root.attributes) {
+        const attrsToRemove = [];
+        for (const attr of Array.from(root.attributes)) {
+            if (isUnsafeAttribute(attr.name, attr.value)) {
+                attrsToRemove.push(attr.name);
+            }
+        }
+        for (const attrName of attrsToRemove) {
+            root.removeAttribute(attrName);
+        }
+    }
+
+    sanitizeElement(root);
+    return svgDocument;
+};
+
+module.exports = sanitizeSvg;
