+/**
+ * Sanitizes a MIME type string to prevent code injection via Content-Type header.
+ * Only allows valid MIME type characters as per RFC 2045/RFC 7231.
+ */
+export function sanitizeMimeType(mimeType: string | undefined): string | undefined {
+  if (!mimeType || typeof mimeType !== 'string') {
+    return undefined;
+  }
+
+  // Extract only the type/subtype portion, discarding parameters
+  const baseType = mimeType.split(';')[0].trim();
+
+  // Validate against RFC-compliant MIME type pattern
+  if (!/^[a-zA-Z0-9][a-zA-Z0-9!#$&\-^_]*\/[a-zA-Z0-9][a-zA-Z0-9!#$&\-^_.+]*$/.test(baseType)) {
+    return undefined;
+  }
+
+  return baseType;
+}
